import fs from 'node:fs';
const seeds=[['phong-nha-hang-toi','Hang Tối'],['phong-nha-nuoc-mooc','Suối Nước Moọc'],['phong-nha-tu-lan','Tú Làn'],['nha-trang-thap-ba-ponagar','Po Nagar'],['nha-trang-hon-chong','Hòn Chồng'],['nha-trang-doc-let','Dốc Lết'],['can-tho-truc-lam-phuong-nam','Thiền viện Trúc Lâm Phương Nam'],['can-tho-munir-ansay','Munir Ansay'],['can-tho-gian-gua','Giàn Gừa'],['vinh-hy-my-nghiep','Làng dệt Mỹ Nghiệp'],['vinh-hy-nam-cuong','Đồi cát Nam Cương'],['vinh-hy-binh-tien','Bình Tiên'],['phu-quoc-suoi-tranh','Suối Tranh'],['phu-quoc-ham-ninh','Làng chài Hàm Ninh'],['phu-yen-bai-mon','Bãi Môn']];
const file='docs/research/geocode-supplement-20261107.json';const report=fs.existsSync(file)?JSON.parse(fs.readFileSync(file,'utf8')):{};
for(const [id,name] of seeds){if(report[id])continue;
try{const params=new URLSearchParams({q:name,countrycodes:'vn',format:'jsonv2',limit:'4'}),r=await fetch('https://nominatim.openstreetmap.org/search?'+params,{headers:{'User-Agent':'WanderCatalog/0.1 (contact: https://github.com/dungv798/Wander)'},signal:AbortSignal.timeout(15000)});if(!r.ok)throw new Error(`HTTP ${r.status}`);report[id]={name,hits:await r.json()};console.log(id,JSON.stringify(report[id].hits.map(h=>({id:h.osm_id,type:h.type,lat:h.lat,lon:h.lon,name:h.display_name}))));}catch(e){report[id]={name,error:e.message};console.log(id,e.message);}fs.writeFileSync(file,JSON.stringify(report,null,2)+'\n');await new Promise(r=>setTimeout(r,1300));}
